var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
return Newtonsoft.Json.JsonConvert.SerializeObject(new {scene = scene.path, playing = Application.isPlaying, objects = scene.GetRootGameObjects().SelectMany(r => r.GetComponentsInChildren<Transform>(true)).Where(t => t.name.Contains("Bed") || t.name.Contains("SideArea") || t.name.Contains("Screen") || t.name.Contains("Spawn") || t.name.Contains("Wall") || t.GetComponent<ThuyKieu.Player.PlayerMovement>() != null || t.GetComponent<ThuyKieu.Interaction.ChapterInteractable>() != null).Select(t => new {path = t.name, position = t.position.ToString(), scale = t.localScale.ToString(), bounds = t.GetComponentsInChildren<Renderer>().Select(r => new {r.name, center = r.bounds.center.ToString(), size = r.bounds.size.ToString()}).ToArray()}).ToArray()});
